import java.time.Duration;
import java.util.*;
import java.util.function.*;

import io.github.resilience4j.core.IntervalFunction;
import io.github.resilience4j.retry.*;

public class Main {
    public static void main(String[] args) {
        GudangPalsu gudang = new GudangPalsu("timeout", "timeout", "timeout", "ok");
        RetryConfig config = RetryConfig.custom()
                .maxAttempts(4)
                .intervalFunction(IntervalFunction.ofExponentialBackoff(100, 2))
                .build();
        Retry retry = Retry.of("gudang", config);
        retry.getEventPublisher().onRetry(e -> System.out.println("ulang ke-" + e.getNumberOfRetryAttempts() + ", tunggu " + e.getWaitInterval().toMillis() + " ms"));
        System.out.println("Stok: " + Retry.decorateSupplier(retry, () -> gudang.cekStok("kopi")).get());
    }
}

class GudangPalsu {
    private final Deque<String> jadwal;
    int panggilan;

    GudangPalsu(String... jadwal) {
        this.jadwal = new ArrayDeque<>(Arrays.asList(jadwal));
    }

    int cekStok(String barang) {
        panggilan++;
        String hasil = jadwal.isEmpty() ? "ok" : jadwal.poll();
        if (hasil.equals("timeout")) {
            throw new IllegalStateException("timeout ke gudang");
        }
        if (hasil.equals("400")) {
            throw new IllegalArgumentException("barang tidak dikenal: " + barang);
        }
        return 7;
    }
}

